#include <cuda_runtime.h>
#include <vector>
#include <algorithm>
#include <cstdint>
#include <cstring>
#define main preserved_original_main
#include "../michalewicz-cuda/main.cu"
#undef main
__global__ void capture_objective(const float*x,float*out,int n,int dim){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n)out[i]=michalewicz(x+i*dim,dim);}
int main(){const int G=4,R=100;const float guard=-1234567.f;FILE*f=fopen("input_f32.bin","rb");if(!f)return 2;fseek(f,0,SEEK_END);size_t length=ftell(f)/4;rewind(f);std::vector<float>input(length);fread(input.data(),4,length,f);fclose(f);f=fopen("oracle_f64.bin","rb");if(!f)return 3;std::vector<double>oracle(26136);fread(oracle.data(),8,oracle.size(),f);fclose(f);bool all=true;
 for(int trial=1;trial<=5;trial++){bool ok=true;int bad=0;double maxerr=0;size_t inputoff=0,oracleoff=0;int pathidx=0;double times[12];std::vector<float>prefix,outputs;
  for(int n:{257,4099})for(int dim:{2,5,10})for(int fixture=0;fixture<2;fixture++){int size=n*dim;std::vector<float>h(size+8,guard),ib(9,guard),out(n+8,guard),actual(h.size()),initial(9),minback(9);std::copy(input.begin()+inputoff,input.begin()+inputoff+size,h.begin()+G);ib[G]=0.f;float *x,*mins,*vals;cudaMalloc(&x,h.size()*4);cudaMalloc(&mins,36);cudaMalloc(&vals,out.size()*4);cudaMemcpy(x,h.data(),h.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(mins,ib.data(),36,cudaMemcpyHostToDevice);cudaMemcpy(vals,out.data(),out.size()*4,cudaMemcpyHostToDevice);
   eval<<<(n+255)/256,256>>>(x+G,mins+G,n,dim);capture_objective<<<(n+255)/256,256>>>(x+G,vals+G,n,dim);ok &=cudaGetLastError()==cudaSuccess&&cudaDeviceSynchronize()==cudaSuccess;cudaMemcpy(mins,ib.data(),36,cudaMemcpyHostToDevice);cudaMemcpy(initial.data(),mins,36,cudaMemcpyDeviceToHost);ok &=initial==ib;cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int repeat=0;repeat<R;repeat++)eval<<<(n+255)/256,256>>>(x+G,mins+G,n,dim);ok &=cudaGetLastError()==cudaSuccess&&cudaDeviceSynchronize()==cudaSuccess;times[pathidx++]=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/R;
   capture_objective<<<(n+255)/256,256>>>(x+G,vals+G,n,dim);ok &=cudaGetLastError()==cudaSuccess&&cudaDeviceSynchronize()==cudaSuccess;cudaMemcpy(actual.data(),x,h.size()*4,cudaMemcpyDeviceToHost);ok &=memcmp(actual.data(),h.data(),h.size()*4)==0;cudaMemcpy(out.data(),vals,out.size()*4,cudaMemcpyDeviceToHost);cudaMemcpy(minback.data(),mins,36,cudaMemcpyDeviceToHost);float captured_min=0.f;double expectedmin=0.;
   for(int i=0;i<G;i++)bad+=out[i]!=guard||out[n+G+i]!=guard||minback[i]!=guard||minback[G+1+i]!=guard;
   for(int i=0;i<n;i++){float value=out[G+i];double expected=oracle[oracleoff+i],error=fabs((double)value-expected);maxerr=std::max(maxerr,error);bad+=!std::isfinite(value)||error>3e-5*dim+1e-5*fabs(expected);if(value<captured_min)captured_min=value;if(expected<expectedmin)expectedmin=expected;}
   bad+=memcmp(&captured_min,&minback[G],4)!=0;double error=fabs((double)minback[G]-expectedmin);maxerr=std::max(maxerr,error);bad+=!std::isfinite(minback[G])||error>3e-5*dim+1e-5*fabs(expectedmin);if(fixture==1){unsigned bits;memcpy(&bits,&minback[G],4);bad+=bits!=0;}
   prefix.insert(prefix.end(),actual.begin(),actual.end());prefix.insert(prefix.end(),initial.begin(),initial.end());outputs.insert(outputs.end(),out.begin(),out.end());outputs.insert(outputs.end(),minback.begin(),minback.end());inputoff+=size;oracleoff+=n;cudaFree(x);cudaFree(mins);cudaFree(vals);
  }ok &=bad==0;all &=ok;std::vector<float>artifact=prefix;artifact.insert(artifact.end(),outputs.begin(),outputs.end());char path[80];snprintf(path,80,"output_trial%d.bin",trial);f=fopen(path,"wb");if(!f)return 4;fwrite(artifact.data(),4,artifact.size(),f);fclose(f);double total=0;for(double v:times)total+=v;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":null,\"timing_region\":\"sum12_source_seeded_GPUmin_windows_per_R100\",\"jit_excluded\":true,\"path_times_seconds\":[",trial,total,ok?"true":"false",artifact.size(),maxerr);for(int j=0;j<12;j++)printf("%s%.12g",j?",":"",times[j]);printf("],\"internal_repeats\":100,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path,artifact.size());
 }puts(all?"PASS":"FAIL");return all?0:1;}
